mapper.select:
SELECT grain AS grain, record_id AS recordId, plan_id AS planId, notice_id AS noticeId, notice_status AS noticeStatus, org_id AS orgId, org_name AS orgName, project_code AS projectCode, project_name AS projectName, demand_type AS demandType, plan_code AS planCode, plan_name AS planName, split_names AS splitNames, scheme_code AS schemeCode, scheme_name AS schemeName, method AS method, control_amount AS controlAmount, purchaser AS purchaser, handler AS handler, plan_effect_time AS planEffectTime, open_time AS openTime, award_time AS awardTime, supplier_name AS supplierName, award_amount AS awardAmount, saving_amount AS savingAmount, saving_rate AS savingRate, contract_code AS contractCode, contract_state AS contractState, status AS status, current_stage AS currentStage, exception_info AS exceptionInfo FROM tb_purchase_ledger
AND ( org_id = #{scopeId} OR org_id IN ( SELECT t.thrid_dept_id FROM sys_dept t WHERE FIND_IN_SET( (SELECT dept_id FROM sys_dept WHERE thrid_dept_id = #{scopeId}), t.ancestors) ) )
AND ( org_id = #{id} OR org_id IN ( SELECT t.thrid_dept_id FROM sys_dept t WHERE FIND_IN_SET( (SELECT dept_id FROM sys_dept WHERE thrid_dept_id = #{id}), t.ancestors) ) )
AND status = #{status}
AND project_code = #{projectCode}
AND project_name like concat('%', #{projectKeyword}, '%')
AND demand_type = #{demandType}
AND method = #{method}
AND current_stage = #{currentStage}
AND handler like concat('%', #{handler}, '%')
AND purchaser like concat('%', #{purchaser}, '%')
AND ( plan_code like concat('%', #{keyword}, '%') OR plan_name like concat('%', #{keyword}, '%') OR scheme_code like concat('%', #{keyword}, '%') OR scheme_name like concat('%', #{keyword}, '%') )
AND plan_effect_time >= #{planEffectBegin}
AND plan_effect_time <= #{planEffectEnd}
ORDER BY
CASE status WHEN 'pending' THEN 0 WHEN 'preopen' THEN 1 WHEN 'preaward' THEN 2 WHEN 'completed' THEN 3 ELSE 4 END, status,
org_name, project_name, record_id
